import hashlib,re,subprocess,sys
fail=[]
def rd(p):
    return open(p,encoding='utf-8').read()
for s in d['sourceLedger']:
    h=hashlib.sha256(open(s['path'],'rb').read()).hexdigest()
    if h!=s['sha256']: fail.append('hash '+s['path'])
loc={}
for l in d['locators']:
    loc[l['id']]=l
    ln=rd(l['file']).split('\n')[l['line']-1]
    if l['token'] not in ln: fail.append('locator '+l['id'])
for r in d['supportRows']:
    for x in r['locators']:
        if x not in loc: fail.append('row '+r['row']+' unknown '+x)
need={'PROOF-OWNER','PROOF-AUTHORITY','PROOF-IDENTITY','PROOF-RECOVERY','PROOF-BOUNDARY'}
have={p for r in d['supportRows'] for p in r['proofIds']}
if not need<=have: fail.append('proof join '+str(need-have))
if {c['id'] for c in d['casePlan']} and any(c['status']!='NOT_EXECUTED_PLANNED' for c in d['casePlan']): fail.append('case status')
panel='EXTENSIONS/CVF_v1.6_AGENT_PLATFORM/cvf-web/src/components/ArtifactExportPanel.tsx'
src=rd(panel)
for tok in ('AbortController','useEffect','beforeunload','signal'):
    if tok in src: fail.append('unexpected '+tok)
m=re.search(r"rawError === '([^']*secret-like[^']*)'",src)
r=re.search(r"error: '([^']*secret-like[^']*)'",rd('EXTENSIONS/CVF_v1.6_AGENT_PLATFORM/cvf-web/src/app/api/artifacts/export/route.ts'))
if not (m and r and m.group(1)!=r.group(1)): fail.append('F-01 mismatch not reproduced')
m2=re.search(r"rawError === '(Missing[^']*)'",src)
r2=re.search(r"error: '(Missing[^']*)'",rd('EXTENSIONS/CVF_v1.6_AGENT_PLATFORM/cvf-web/src/app/api/artifacts/export/route.ts'))
if not (m2 and r2 and m2.group(1)==r2.group(1)): fail.append('missing-field literal drift')
en=src.split('  en: {')[1].split('  vi: {')[0]
vi=src.split('  vi: {')[1].split('const PRINT_FRAME_WIDTH')[0]
k=lambda t:set(re.findall(r'^    (\w+): ',t,re.M))
if k(en)!=k(vi): fail.append('label key parity '+str(k(en)^k(vi)))
out=subprocess.run(['git','status','--short','--untracked-files=all'],capture_output=True,text=True).stdout.split('\n')
exp={'?? docs/reference/CVF_NCR_R1_HTML_UX_SUPPORT_AUDIT_2026-10-02.md','?? docs/reviews/evidence/cvf-ncr-r1-html-ux-support-audit-2026-10-02.json','?? docs/reviews/CVF_CVF_NCR_R1_HTML_UX_SUPPORT_AUDIT_WORKER_RETURN_2026-10-02.md'}
if {x.strip() for x in out if x.strip()}!=exp: fail.append('diff set '+repr(out))
print('FAIL' if fail else 'PASS_STATIC_ONLY',fail)
sys.exit(1 if fail else 0)
